import zipfile, io

# Count sequences using grep-style approach
def count_fasta_seqs(filename):
    count = 0
    with open(filename) as f:
        for line in f:
            if line.startswith('>'):
                count += 1
    return count

for faa in sorted(['Fungi_Scer.faa', 'Fungi_Ncra.faa', 'Fungi_Spom.faa', 'Fungi_Umay.faa',
